DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.command_chain(uuid,boolean)'::regprocedure) INTO d; d:=replace(d,'IF role_needed IS NOT NULL AND NOT public.has_any_role(a.user_id,ARRAY[role_needed]) THEN','IF cardinality(ids)=3 AND x=1 AND NOT public.has_any_role(a.user_id,ARRAY[''chief_instructor'',''dc_academy'']::app_role[]) THEN RAISE EXCEPTION ''Assigned supervisor needs Chief Instructor authorization''; END IF; IF role_needed IS NOT NULL AND NOT (cardinality(ids)=3 AND x=1) AND NOT public.has_any_role(a.user_id,ARRAY[role_needed]) THEN'); EXECUTE d; SELECT pg_get_functiondef('public.compile_daily_reports(jsonb)'::regprocedure) INTO d; d:=replace(d,'r.chain->4->>''user_id''','r.chain->(jsonb_array_length(r.chain)-1)->>''user_id'''); EXECUTE d; END $$;